</div>

        <script>
          document.addEventListener('DOMContentLoaded', function() {
            const filterBtns = document.querySelectorAll('.filter-btn');
            const jobCards = document.querySelectorAll('.job-card');

            filterBtns.forEach(btn => {
              btn.addEventListener('click', () => {
                // Remove active class from all buttons and add to clicked
                filterBtns.forEach(b => {
                  b.classList.remove('active');
                  b.style.background = 'white';
                  b.style.color = '#333';
                });
                
                btn.classList.add('active');
                btn.style.background = '#3b90c3';
                btn.style.color = 'white';

                const filterValue = btn.getAttribute('data-filter');

                let delay = 0;
                jobCards.forEach(card => {
                  card.style.display = 'none';
                  card.style.animation = 'none';
                  card.style.opacity = '0';
                  
                  if (card.getAttribute('data-department') === filterValue) {
                    card.style.display = 'block';
                    // Staggered animation effect
                    setTimeout(() => {
                      card.style.animation = 'scaleIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards';
                      setTimeout(() => {
                        card.style.animation = '';
                        card.style.opacity = '1';
                      }, 450);
                    }, delay);
                    delay += 50; // stagger each card by 50ms
                  }
                });
              });
            });

            const jobModal = document.getElementById('jobModal');
            if(jobModal) {
              // Move modal to body to prevent stacking context issues with the backdrop
              document.body.appendChild(jobModal);
              
              jobModal.addEventListener('show.bs.modal', function (event) {
                const card = event.relatedTarget;
                
                // Calculate position for zoom effect
                const rect = card.getBoundingClientRect();
                const cardCenterX = rect.left + rect.width / 2;
                const cardCenterY = rect.top + rect.height / 2;
                const offsetX = cardCenterX - (window.innerWidth / 2);
                const offsetY = cardCenterY - (window.innerHeight / 2);
                
                const dialog = jobModal.querySelector('.modal-dialog');
                dialog.style.transformOrigin = `calc(50% + ${offsetX}px) calc(50% + ${offsetY}px)`;
                const title = card.getAttribute('data-job-title');
                const desc = card.getAttribute('data-job-desc');
                
                const modalTitle = jobModal.querySelector('.modal-title');
                const modalDesc = jobModal.querySelector('#jobModalDesc');
                const modalApplyBtn = jobModal.querySelector('#jobModalApplyBtn');
                
                modalTitle.textContent = title;
                modalDesc.textContent = desc;
                modalApplyBtn.href = 'application.php?position=' + encodeURIComponent(title);
              });
            }
            
            // Prevent modal from opening if they click the Apply Now button directly on the card
            document.querySelectorAll('.job-card .btn-outline').forEach(btn => {
              btn.addEventListener('click', function(e) {
                e.stopPropagation();
              });
            });

          });
        </script>
        

      </div>
